const CACHE='zero-one-practice-lab-1.3.4-brand-20261007g';  // 配信版とオフライン更新の識別を1.3.4へ揃えます。
const FILES=['./','./index.html','./style.css','./series.css','./draft.mjs','./save-status.mjs','./catalog.mjs','./picker.mjs','./media-model.mjs','./media-store.mjs','./media-cloud.mjs','./media-session.mjs','./media-import-policy.mjs','./reference-links.mjs','./icons/icon-192.webp','./icons/icon-512.webp','./icons/apple-touch-icon.png','./app.mjs','./ui.mjs','./worker-bridge.mjs','./auth.mjs','./config.mjs','./worker.js','./manifest.webmanifest','./core/hash.mjs','./core/model.mjs','./core/repository.mjs','./core/sync.mjs','./core/graph.mjs','./core/connection.mjs','./core/planner.mjs','./core/service.mjs','./menu-structures.mjs','./core/wasm-driver.mjs','./data/terms.sample.json','./data/terms.json','./vendor/sqlite3.js','./vendor/sqlite3.wasm','./vendor/msal-browser.min.js']; 
const urls=new Set(FILES.map(f=>new URL(f,self.registration.scope).href)); 
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES)));}); 
self.addEventListener('activate',event=>{event.waitUntil(Promise.resolve());}); 
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||!urls.has(event.request.url))return;event.respondWith(caches.open(CACHE).then(async cache=>(await cache.match(event.request))||fetch(event.request)));}); 
self.addEventListener('message',event=>{if(event.data?.type==='offlineCheck')event.waitUntil(caches.open(CACHE).then(async cache=>{const ready=(await Promise.all(FILES.map(f=>cache.match(f)))).every(Boolean);event.source?.postMessage({type:'offlineStatus',appShellReady:ready,version:'1.3.4'});}));});  // 配信版とオフライン更新の識別を1.3.4へ揃えます。
